     1→# ============================================================================
     2→# Phase C Task C.2: Julia Parser 이식 (FreeLang 구현)
     3→# ============================================================================
     4→# Julia 컴파일러의 파서(Parser) 모듈을 FreeLang으로 이식합니다.
     5→#
     6→# 기능:
     7→# - AST (Abstract Syntax Tree) 노드 정의
     8→# - 재귀 하강 파서 구현
     9→# - 연산자 우선순위 (Precedence climbing)
    10→# - 문 파싱 (함수, 구조체, 제어 흐름 등)
    11→# - 표현식 파싱 (이항, 단항, 후위 연산)
    12→#
    13→# 목표: Go 파서와 100% 호환
    14→# 규모: 550줄 (구현 + 테스트)
    15→# ============================================================================
    16→
    17→# ============================================================================
    18→# Part 1: AST 노드 정의
    19→# ============================================================================
    20→
    21→# Expr (표현식)
    22→record IntLiteral {
    23→  value: Int,
    24→}
    25→
    26→record FloatLiteral {
    27→  value: Float,
    28→}
    29→
    30→record StringLiteral {
    31→  value: String,
    32→}
    33→
    34→record BoolLiteral {
    35→  value: Bool,
    36→}
    37→
    38→record Identifier {
    39→  name: String,
    40→}
    41→
    42→record BinaryOp {
    43→  left: Expr,
    44→  op: String,      # "+", "-", "*", "/", "==", "<" 등
    45→  right: Expr,
    46→}
    47→
    48→record UnaryOp {
    49→  op: String,      # "-", "!", "~" 등
    50→  operand: Expr,
    51→}
    52→
    53→record Call {
    54→  function: Expr,
    55→  args: [Expr],
    56→}
    57→
    58→record Index {
    59→  array: Expr,
    60→  index: Expr,
    61→}
    62→
    63→record MemberAccess {
    64→  object: Expr,
    65→  member: String,
    66→}
    67→
    68→# Stmt (문)
    69→record ExprStmt {
    70→  expr: Expr,
    71→}
    72→
    73→record FunctionDecl {
    74→  name: String,
    75→  params: [String],
    76→  body: [Stmt],
    77→}
    78→
    79→record StructDecl {
    80→  name: String,
    81→  fields: [(String, String)],  # (fieldName, fieldType)
    82→}
    83→
    84→record IfStmt {
    85→  condition: Expr,
    86→  then_branch: [Stmt],
    87→  else_branch: Option[[Stmt]],
    88→}
    89→
    90→record WhileStmt {
    91→  condition: Expr,
    92→  body: [Stmt],
    93→}
    94→
    95→record ForStmt {
    96→  variable: String,
    97→  iterable: Expr,
    98→  body: [Stmt],
    99→}
   100→

